import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str) or not os.path.isfile(script_path):
        raise FileNotFoundError(f"Script path not valid: {script_path}")
    proc = subprocess.Popen(['bash', script_path])
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    total_cpu = 0.0
    total_mem = 0
    start = time.time()
    while True:
        time.sleep(0.1)
        elapsed = time.time() - start
        if elapsed > timeout:
            proc.terminate()
            proc.wait()
            break
        try:
            if p.status() == psutil.STATUS_ZOMBIE:
                break
            cpu = p.cpu_percent(interval=0)
            mem = p.memory_info().rss
            total_cpu += cpu
            total_mem += mem
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    if proc.poll() is None:
        proc.terminate()
        proc.wait()
    else:
        proc.wait()
    return {'CPU Usage': total_cpu, 'Memory Usage': total_mem}
